const criteriaKeys=['contentPass','performancePass','scalePass','activityPass','brandFitPass'];

function creatorState(creator,stage){
  if(stage===0)return 'unassessed';
  const previous=criteriaKeys.slice(0,stage-1).map(key=>creator[key]);
  if(previous.some(value=>value!==true))return 'hidden';
  const current=creator[criteriaKeys[stage-1]];
  if(current===false)return 'failed';
  if(current==='unknown')return 'unknown';
  return 'passed';
}

function stageSummary(stage){
  return creators.reduce((out,creator)=>{out[creatorState(creator,stage)]++;return out},{passed:0,unknown:0,failed:0,hidden:0,unassessed:0});
}

// Presentation-only Brand Fit enrichment. Source-backed HoYoverse ratios are retained;
// missing ratios and competitor shares are illustrative estimates for the prototype.
const brandFitPresentation={
  C01:{hoyoverseContentRatio:.88,competitorContentRatio:.08,ratioSource:'illustrative',contentConductSafety:'pass',leakPiracyRisk:'pass',originalityRisk:'pass'},
  C02:{competitorContentRatio:0,ratioSource:'mixed',contentConductSafety:'pass',leakPiracyRisk:'pass',originalityRisk:'pass'},
  C03:{competitorContentRatio:.60,ratioSource:'mixed',contentConductSafety:'pass',leakPiracyRisk:'pass',originalityRisk:'fail'},
  C05:{competitorContentRatio:.20,ratioSource:'mixed',contentConductSafety:'pass',leakPiracyRisk:'pass',originalityRisk:'pass'},
  C07:{hoyoverseContentRatio:.55,competitorContentRatio:.35,ratioSource:'illustrative',contentConductSafety:'pass',leakPiracyRisk:'pass',originalityRisk:'pass'}
};
creators.forEach(creator=>Object.assign(creator.brandFit,brandFitPresentation[creator.id]||{}));



const STAGES=[
  ['00','UNIVERSE','START WITH THE POOL'],['01','CONTENT','CONTENT RELEVANCE'],
  ['02','PERFORMANCE','RECENT PERFORMANCE'],['03','SCALE','CREATOR SCALE'],
  ['04','ACTIVITY','ACTIVE & CONSISTENT'],['05','BRAND FIT','BRAND FIT']
];
const READOUTS=[
  ['UNIVERSE INTAKE','No criteria applied. All sample creators begin embedded within the wider visual universe.'],
  ['CONTENT RELEVANCE','Confirm that each creator’s content aligns with the campaign audience and priority formats.'],
  ['RECENT PERFORMANCE','Keep creators who also meet the 30-day average-view reference for this screening model.'],
  ['CREATOR SCALE','Apply the target follower range. The spherical pool begins revealing its underlying data structure.'],
  ['ACTIVITY','Review recent activity and posting consistency without treating missing evidence as a pass or fail.'],
  ['BRAND FIT','Compare HoYoverse and competitor content share, brand safety and final client approval.']
];
const canvas=document.querySelector('#universe');
const shell=document.querySelector('.prototype-shell');
const viewport=document.querySelector('.viewport');
const nav=document.querySelector('.stages');
const subtitle=document.querySelector('#stage-subtitle');
const tooltip=document.querySelector('.tooltip');
const selectionTarget=document.querySelector('.selection-target');
const selectionLine=document.querySelector('.selection-line');
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const particleCount=innerWidth<720?1400:2300;
let stage=Math.max(0,Math.min(5,Number(new URLSearchParams(location.search).get('stage')||0)));
let displayStage=stage,playToken=0,hovered=-1,selectedCreator=0,lastTime=performance.now(),fpsFrames=0,fpsStart=lastTime;
const pointer={x:-999,y:-999};

nav.innerHTML=STAGES.map(([n,label],i)=>`<button data-stage="${i}" aria-label="Stage ${n}: ${label}"><small>${n}</small>${label}</button>`).join('');
nav.addEventListener('click',e=>{const button=e.target.closest('[data-stage]');if(button)setStage(Number(button.dataset.stage));});
document.querySelector('#reset').addEventListener('click',()=>setStage(0));
document.querySelector('#play').addEventListener('click',playSequence);
document.querySelector('#profile-prev').addEventListener('click',()=>selectCreator(selectedCreator-1));
document.querySelector('#profile-next').addEventListener('click',()=>selectCreator(selectedCreator+1));
window.addEventListener('keydown',e=>{if(e.key>='0'&&e.key<='5')setStage(Number(e.key));if(e.key==='ArrowRight')setStage(Math.min(5,stage+1));if(e.key==='ArrowLeft')setStage(Math.max(0,stage-1));});

function setStage(next,{keepSequence=false}={}){
  if(!keepSequence)playToken++;
  stage=next;
  shell.className=`prototype-shell stage-${stage}`;
  subtitle.textContent=`${STAGES[stage][0]} — ${STAGES[stage][2]}`;
  [...nav.children].forEach((b,i)=>{b.classList.toggle('active',i===stage);b.setAttribute('aria-current',i===stage?'step':'false')});
  const summary=stageSummary(stage);
  viewport.dataset.summary=`${summary.passed} confirmed · ${summary.unknown} not assessed · ${summary.failed} filtered`;
  document.querySelector('#readout-title').textContent=READOUTS[stage][0];
  document.querySelector('#readout-copy').textContent=READOUTS[stage][1];
  document.querySelector('#count-pass').textContent=stage===0?'—':summary.passed;
  document.querySelector('#count-unknown').textContent=stage===0?summary.unassessed:summary.unknown;
  document.querySelector('#count-unknown-label').textContent=stage===0?'IN SAMPLE':stage===5?'PENDING REVIEW':'NOT ASSESSED';
  document.querySelector('#count-fail').textContent=summary.failed;
  document.querySelector('#metric-pass').hidden=stage===0;
  document.querySelector('#metric-unknown').hidden=stage>0&&stage<5;
  document.querySelector('#metric-fail').hidden=stage===0;
  document.querySelector('#legend-unknown').hidden=stage<5;
  if(creatorState(creators[selectedCreator],stage)==='hidden')selectedCreator=Math.max(0,creators.findIndex(creator=>creatorState(creator,stage)!=='hidden'));
  renderProfile();
  tooltip.classList.remove('visible');selectionTarget.classList.remove('visible');selectionLine.classList.remove('visible');hovered=-1;
}

async function playSequence(){
  const token=++playToken;
  document.querySelector('#play').textContent='PLAYING';
  const holds=[2000,2100,1900,1900,1900,3000];
  for(let i=0;i<6&&token===playToken;i++){
    setStage(i,{keepSequence:true});
    await new Promise(resolve=>setTimeout(resolve,reduced?450:holds[i]));
  }
  if(token===playToken)document.querySelector('#play').textContent='PLAY SEQUENCE';
}
window.setPrototypeStage=setStage;
setStage(stage);

function selectCreator(index){const direction=index<selectedCreator?-1:1;let next=(index+creators.length)%creators.length;for(let i=0;i<creators.length;i++){if(creatorState(creators[next],stage)!=='hidden'){selectedCreator=next;renderProfile();return}next=(next+direction+creators.length)%creators.length}}
function displayValue(value){if(value===null||value===undefined||value==='unknown')return 'Unavailable';if(value===true||value==='pass')return 'Matched';if(value===false||value==='fail')return 'Not matched';if(typeof value==='number')return Number.isInteger(value)?value.toLocaleString():`${Math.round(value*100)}%`;return String(value).replaceAll('_',' ')}
function resultClass(value){return value===true||value==='pass'||value==='within'||value==='consistent'||value==='high'||value==='safe'?'pass':value===false||value==='fail'||value==='below'||value==='above'||value==='risk'||value==='rejected'||value==='low'||value==='inconsistent'?'fail':'unknown'}
function criterion(label,value,detail){const state=resultClass(value);return `<div class="criterion ${state}"><i>${state==='pass'?'✓':state==='fail'?'×':'·'}</i><b>${label}</b><small>${detail??displayValue(value)}</small></div>`}
function renderProfile(){
  const c=creators[selectedCreator],stageKey=['content','content','performance','scale','activity','brandFit'][stage],data=c[stageKey];
  document.querySelector('#profile-index').textContent=`${String(selectedCreator+1).padStart(2,'0')} / ${creators.length}`;
  document.querySelector('#profile-id').textContent=`CREATOR ${c.id}`;
  document.querySelector('#profile-meta').innerHTML=`${c.platform.toUpperCase()} · ${String(c.region).toUpperCase()}<br>${format(c.followers)} FOLLOWERS · ${format(c.avgViews)} AVG. VIEWS`;
  document.querySelector('#profile-stage-count').textContent=`${String(stage).padStart(2,'0')} / 05`;
  document.querySelector('#profile-stage').textContent=stage===0?'INITIAL STATE':STAGES[stage][2];
  let rows='';
  if(stage===0){rows=['CONTENT RELEVANCE','RECENT PERFORMANCE','CREATOR SCALE','ACTIVITY','BRAND FIT'].map(label=>criterion(label,'unknown','Not assessed')).join('')}
  if(stage===1){const types=data.contentTypes||[];rows=criterion('Published HoYoverse game content',data.result,data.result==='pass'?'Matched':'Not matched')+criterion('Content types',types.length?'pass':'unknown',types.length?types.map(displayValue).join(', '):'Not detected')+criterion('ACG-related content',data.acgRelated,data.acgRelated==='unknown'?'Not detected':displayValue(data.acgRelated))+criterion('Fan creation / cosplay',data.fanCreation,data.fanCreation==='unknown'?'Not detected':displayValue(data.fanCreation))}
  if(stage===2){rows=criterion('30-day average views',data.result,`${format(data.avgViews)} / ${data.threshold?.operator||'≥'} ${format(data.threshold?.value)}`)+criterion('Recorded view range',data.minViews!=null&&data.maxViews!=null?'pass':'unknown',`${format(data.minViews)}–${format(data.maxViews)}`)+criterion('Engagement rate',data.engagementRate==null?'unknown':'pass',data.engagementRate==null?'Not used':displayValue(data.engagementRate))}
  if(stage===3){rows=criterion('Follower target range',data.result,`${format(data.followers)} / ${format(data.targetRange?.min)}–${format(data.targetRange?.max)}`)+criterion('Range position',data.position)+criterion('Creator tier',data.tier==='unknown'?'unknown':'pass',displayValue(data.tier))}
  if(stage===4){const range=data.monthlyUploadRange||{},proxy=data.result==='pass'&&data.weeklyActive==='unknown',frequency=range.min==null?'Upload frequency':`Upload frequency (${range.min}–${range.max}/month)`,status=value=>resultClass(value)==='pass'?'Matched':resultClass(value)==='fail'?'Not matched':'Pending review';rows=criterion(frequency,range.min==null?'unknown':'pass',range.min==null?'Pending review':'Matched')+criterion(proxy?'Posting consistency (monthly evidence)':'Posting consistency',proxy?'pass':data.postingConsistency,status(proxy?'pass':data.postingConsistency))+criterion(proxy?'Activity cadence (monthly evidence)':'Weekly activity standard',data.result,status(data.result))}
  if(stage===5){const status=value=>resultClass(value)==='pass'?'Matched':resultClass(value)==='fail'?'Not matched':'Pending review',pct=value=>value==null?'—':`${Math.round(value*100)}%`,concentrationLevel=value=>value==null?'Pending review':value>=.50?'High':value>=.10?'Medium':'Low',hoyo=data.hoyoverseContentRatio==null?'unknown':data.hoyoverseContentRatio>=.10?'pass':'fail',competitor=data.competitorContentRatio==null?'unknown':data.competitorContentRatio<.50?'pass':'fail',safety=[data.brandSafety,data.contentConductSafety,data.leakPiracyRisk,data.originalityRisk].some(value=>resultClass(value)==='fail')?'fail':[data.contentConductSafety,data.leakPiracyRisk,data.originalityRisk].every(value=>resultClass(value)==='pass')?'pass':'unknown',eligibleForApproval=[hoyo,competitor,safety].every(value=>resultClass(value)==='pass'),approval=eligibleForApproval?data.internalReview:'unknown';rows=criterion(`HoYoverse content share (${pct(data.hoyoverseContentRatio)})`,hoyo,concentrationLevel(data.hoyoverseContentRatio))+criterion(`Competitor content share (${pct(data.competitorContentRatio)})`,competitor,concentrationLevel(data.competitorContentRatio))+criterion('Brand safety',safety,status(safety))+criterion('Client / brand approval',approval,eligibleForApproval?status(approval):'Not reached')}
  document.querySelector('#profile-criteria').innerHTML=rows;
  const note=document.querySelector('#profile-note');
  const proxyNote=stage===4&&data.result==='pass'&&data.weeklyActive==='unknown';
  note.hidden=!proxyNote;
  note.textContent=proxyNote?'Weekly distribution is not recorded. The activity result uses the recorded monthly minimum of at least four uploads and the absence of low-frequency, inactivity, or inconsistency flags.':'';
  let state=stage===0?'unknown':resultClass(data.result);if(stage>0&&stage<5&&state==='unknown')state='fail';const verdict=document.querySelector('#profile-verdict');verdict.className=`profile-verdict ${state}`;verdict.querySelector('i').textContent=state==='pass'?'✓':state==='fail'?'×':'i';verdict.querySelector('b').textContent=stage===0?'NOT SCREENED YET':state==='pass'?'PASSED':state==='fail'?'FILTERED AT THIS STAGE':'PENDING REVIEW';verdict.querySelector('span').textContent=stage===0?'This creator is part of the full universe.':stage===1?(state==='pass'?'Published HoYoverse game content is documented.':'No HoYoverse game content is documented in the selected record.'):state==='pass'?'Creator meets the recorded criteria for this stage.':state==='fail'?(data.result==='unknown'?'Required evidence is missing, so this creator is filtered at this stage.':'Creator does not meet one or more recorded criteria.'):'Awaiting client / brand approval.';
}

const gl=canvas.getContext('webgl',{alpha:false,antialias:true,powerPreference:'high-performance',preserveDrawingBuffer:true});
if(!gl){viewport.innerHTML='<p class="webgl-error">WebGL is required for this motion prototype.</p>';throw new Error('WebGL unavailable')}

const VERT=`
precision highp float;
attribute vec3 aPosition;
attribute vec3 aSeed;
uniform float uTime,uStage,uAspect,uReduced,uOffset;
varying float vAlpha,vGlow,vDepth;
void main(){
  float progress=uStage/5.0;
  float density=mix(1.0,.15,progress);
  float peeled=smoothstep(density-.05,density+.08,aSeed.x);
  float t=uTime*(1.0-uReduced);
  vec3 p=aPosition;
  float wave=sin(p.y*5.2+t*.42+aSeed.y*5.0)*.025+sin(p.x*7.0-t*.27)*.013;
  p*=1.0+wave+sin(t*.36+aSeed.z*6.28)*.012;
  float angle=t*.055;
  float ca=cos(angle),sa=sin(angle);
  p.xz=mat2(ca,-sa,sa,ca)*p.xz;
  p.y+=sin(t*.3+aSeed.y*8.0)*.018;
  vec3 drift=normalize(aPosition+vec3(.001))*(.18+.52*progress)*peeled;
  drift+=vec3((aSeed.y-.5)*.58,(aSeed.z-.42)*.42,(aSeed.x-.5)*.45)*peeled*progress;
  p+=drift;
  float persp=2.62/(3.4-p.z);
  gl_Position=vec4(p.x*persp/uAspect+uOffset,p.y*persp,p.z*.06,1.0);
  float depth=clamp((p.z+1.3)/2.6,0.0,1.0);
  gl_PointSize=(1.8+depth*2.35)*(1.0+sin(aSeed.z*30.0)*.12);
  vAlpha=mix(mix(.9,.34,progress),.04,peeled)*mix(.68,1.0,depth);
  vGlow=0.0;vDepth=depth;
}`;
const FRAG=`
precision highp float;varying float vAlpha,vGlow,vDepth;
void main(){vec2 p=gl_PointCoord-.5;float d=length(p);float core=1.0-smoothstep(.18,.5,d);if(core<=0.0)discard;vec3 ivory=vec3(.95,.91,.84);gl_FragColor=vec4(ivory*(.72+vDepth*.28),core*vAlpha);}`;
const DATA_VERT=`
precision highp float;
attribute vec3 aPosition;attribute vec2 aScatter;attribute vec4 aCriteria;attribute float aBrand;attribute float aSeed;
uniform float uTime,uStage,uAspect,uReduced,uHover,uOffset;
varying vec3 vColor;varying float vAlpha,vHalo,vPassed;
float statusAt(float count){
  if(count<.5)return 1.0;
  float hidden=0.0;
  if(count>=2.0)hidden=max(hidden,1.0-step(.5,aCriteria.x));
  if(count>=3.0)hidden=max(hidden,1.0-step(.5,aCriteria.y));
  if(count>=4.0)hidden=max(hidden,1.0-step(.5,aCriteria.z));
  if(count>=5.0)hidden=max(hidden,1.0-step(.5,aCriteria.w));
  if(hidden>.5)return 3.0;
  float current=count<1.5?aCriteria.x:count<2.5?aCriteria.y:count<3.5?aCriteria.z:count<4.5?aCriteria.w:aBrand;
  if(current<-.5)return 2.0;if(abs(current)<.5)return 1.0;return 0.0;
}
vec3 stateColor(float s){if(s<.5)return vec3(.58,1.0,.08);if(s<1.5)return vec3(.95,.82,.56);if(s<2.5)return vec3(.92,.25,.20);return vec3(.0);}
void main(){
  float low=floor(uStage);float high=min(5.0,ceil(uStage));float blend=smoothstep(.08,.86,fract(uStage));
  float stateLow=statusAt(low),stateHigh=statusAt(high);float failed=mix(step(1.5,stateLow)*(1.0-step(2.5,stateLow)),step(1.5,stateHigh)*(1.0-step(2.5,stateHigh)),blend);float hidden=mix(step(2.5,stateLow),step(2.5,stateHigh),blend);
  float t=uTime*(1.0-uReduced);vec3 p=aPosition;
  float angle=t*.055;float ca=cos(angle),sa=sin(angle);p.xz=mat2(ca,-sa,sa,ca)*p.xz;
  p*=1.0+sin(t*.34+aSeed*11.0)*.014;p.y+=sin(t*.45+aSeed*17.0)*.018;
  p+=normalize(aPosition+vec3(.001))*failed*smoothstep(0.0,1.0,uStage)*.32;
  float persp=2.62/(3.4-p.z);vec2 sphere=vec2(p.x*persp/uAspect,p.y*persp);
  float morph=smoothstep(2.25,5.0,uStage);vec2 finalPos=mix(sphere,aScatter,morph);
  // The final surviving cohort trends high on the data axis. Preserve its
  // internal ranking while easing its visual centroid back to the canvas center.
  float finalSurvivor=1.0-step(1.5,statusAt(5.0));
  float centerPull=smoothstep(3.65,5.0,uStage);
  finalPos.y-=.54*finalSurvivor*centerPull;
  float isC03=1.0-step(.0005,abs(aSeed-.0892857));
  float c03BrandMove=smoothstep(4.45,5.0,uStage);
  finalPos+=vec2(.62,-.08)*isC03*c03BrandMove;
  finalPos.x+=uOffset*(1.0-morph*.35);
  gl_Position=vec4(finalPos,mix(p.z*.06,0.0,morph),1.0);
  float passed=mix(1.0-step(.5,stateLow),1.0-step(.5,stateHigh),blend);
  float pending=(1.0-failed)*(1.0-passed);
  float pulse=.5+.5*sin(t*1.3+aSeed*19.0);
  float statusScale=1.28;
  float selected=1.0-step(.0015,abs(aSeed-uHover));
  gl_PointSize=(mix(8.5,12.5,morph)+pulse*1.2)*statusScale*(1.0+selected*.75)*(1.0-hidden);
  vColor=mix(stateColor(stateLow),stateColor(stateHigh),blend);vAlpha=1.0-hidden;vHalo=.62+passed*.38;vPassed=passed;
}`;
const DATA_FRAG=`
precision highp float;varying vec3 vColor;varying float vAlpha,vHalo,vPassed;
void main(){float d=length(gl_PointCoord-.5);float alpha=(1.0-smoothstep(.12,.5,d))*vAlpha;if(alpha<=0.0)discard;float glow=(1.0-smoothstep(.05,.5,d))*(.26+.3*vPassed)*vHalo;gl_FragColor=vec4(vColor+glow,alpha);}`;

function shader(type,source){const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(s));return s}
function program(vs,fs){const p=gl.createProgram();gl.attachShader(p,shader(gl.VERTEX_SHADER,vs));gl.attachShader(p,shader(gl.FRAGMENT_SHADER,fs));gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(p));return p}
function mulberry32(seed){return()=>{let t=seed+=0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
function spherePoint(rand,radius=1){const z=rand()*2-1,a=rand()*Math.PI*2,r=Math.sqrt(1-z*z),volume=Math.pow(rand(),.18)*radius;return [r*Math.cos(a)*volume,z*volume,r*Math.sin(a)*volume]}
function makeAttrib(p,name,data,size){const loc=gl.getAttribLocation(p,name),buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(data),gl.STATIC_DRAW);return {loc,buffer,size}}
function bindAttribs(attributes){for(const a of attributes){gl.bindBuffer(gl.ARRAY_BUFFER,a.buffer);gl.enableVertexAttribArray(a.loc);gl.vertexAttribPointer(a.loc,a.size,gl.FLOAT,false,0,0)}}
function uniform(p,name){return gl.getUniformLocation(p,name)}
function encode(v){return v===true?1:v===false?-1:0}
function logMap(value,min,max,a,b){return a+(Math.log(value)-Math.log(min))/(Math.log(max)-Math.log(min))*(b-a)}

const random=mulberry32(20260922),visualPositions=[],visualSeeds=[];
for(let i=0;i<particleCount;i++){visualPositions.push(...spherePoint(random,1.08));visualSeeds.push(random(),random(),random())}
const dataRandom=mulberry32(42819),dataPositions=[],dataScatter=[],dataCriteria=[],dataBrand=[],dataSeeds=[];
creators.forEach((c,i)=>{dataPositions.push(...spherePoint(dataRandom,1.04));dataScatter.push(logMap(c.followers,3400,1250000,-.76,.76),logMap(c.avgViews,246,118000,-.68,.68));dataCriteria.push(encode(c.contentPass),encode(c.performancePass),encode(c.scalePass),encode(c.activityPass));dataBrand.push(encode(c.brandFitPass));dataSeeds.push((i+.5)/creators.length)});

const visualProgram=program(VERT,FRAG),dataProgram=program(DATA_VERT,DATA_FRAG);
const visualAttributes=[makeAttrib(visualProgram,'aPosition',visualPositions,3),makeAttrib(visualProgram,'aSeed',visualSeeds,3)];
const embedOffset=document.documentElement.classList.contains('portfolio-embed')?.14:0;
const vu={time:uniform(visualProgram,'uTime'),stage:uniform(visualProgram,'uStage'),aspect:uniform(visualProgram,'uAspect'),reduced:uniform(visualProgram,'uReduced'),offset:uniform(visualProgram,'uOffset')};
const dataAttributes=[makeAttrib(dataProgram,'aPosition',dataPositions,3),makeAttrib(dataProgram,'aScatter',dataScatter,2),makeAttrib(dataProgram,'aCriteria',dataCriteria,4),makeAttrib(dataProgram,'aBrand',dataBrand,1),makeAttrib(dataProgram,'aSeed',dataSeeds,1)];
const du={time:uniform(dataProgram,'uTime'),stage:uniform(dataProgram,'uStage'),aspect:uniform(dataProgram,'uAspect'),reduced:uniform(dataProgram,'uReduced'),hover:uniform(dataProgram,'uHover'),offset:uniform(dataProgram,'uOffset')};

function resize(){const dpr=Math.min(devicePixelRatio||1,1.75),rect=canvas.getBoundingClientRect();const w=Math.max(1,Math.round(rect.width*dpr)),h=Math.max(1,Math.round(rect.height*dpr));if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;gl.viewport(0,0,w,h)}}
function smoothstep(a,b,x){x=Math.max(0,Math.min(1,(x-a)/(b-a)));return x*x*(3-2*x)}
function dataScreenPositions(time){
  const rect=canvas.getBoundingClientRect(),aspect=rect.width/rect.height,morph=smoothstep(2.25,5,displayStage),angle=time*.055,out=[];
  for(let i=0;i<creators.length;i++){
    let x=dataPositions[i*3],y=dataPositions[i*3+1],z=dataPositions[i*3+2],seed=dataSeeds[i];
    const breath=1+Math.sin(time*.34+seed*11)*.014;x*=breath;y*=breath;z*=breath;y+=Math.sin(time*.45+seed*17)*.018;
    if(creatorState(creators[i],Math.round(displayStage))==='failed'){
      const length=Math.hypot(x,y,z)||1,peel=.32*smoothstep(0,1,displayStage);x+=x/length*peel;y+=y/length*peel;z+=z/length*peel;
    }
    // Match GLSL's column-major mat2(ca,-sa,sa,ca) rotation exactly.
    const ca=Math.cos(angle),sa=Math.sin(angle),rx=ca*x+sa*z,rz=-sa*x+ca*z,scale=2.62/(3.4-rz);
    const sx=rx*scale/aspect,sy=y*scale;
    const finalState=creatorState(creators[i],5),finalSurvivor=finalState==='passed'||finalState==='unknown'?1:0;
    const centerPull=smoothstep(3.65,5,displayStage);
    let nx=sx+(dataScatter[i*2]-sx)*morph+embedOffset*(1-morph*.35),ny=sy+(dataScatter[i*2+1]-sy)*morph-.54*finalSurvivor*centerPull;
    if(creators[i].id==='C03'){const c03BrandMove=smoothstep(4.45,5,displayStage);nx+=.62*c03BrandMove;ny-=.08*c03BrandMove}
    out.push({x:(nx*.5+.5)*rect.width,y:(.5-ny*.5)*rect.height,visible:creatorState(creators[i],Math.round(displayStage))!=='hidden'});
  }return out;
}
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=e.clientX-r.left;pointer.y=e.clientY-r.top});
canvas.addEventListener('pointerleave',()=>{pointer.x=-999;tooltip.classList.remove('visible');selectionTarget.classList.remove('visible');selectionLine.classList.remove('visible');hovered=-1});

function render(now){
  resize();const rect=canvas.getBoundingClientRect(),aspect=rect.width/rect.height,time=now/1000;
  const ease=reduced?1:.045;displayStage+=(stage-displayStage)*ease;if(Math.abs(stage-displayStage)<.002)displayStage=stage;
  gl.disable(gl.DEPTH_TEST);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);gl.clearColor(.031,.039,.031,1);gl.clear(gl.COLOR_BUFFER_BIT);
  gl.useProgram(visualProgram);bindAttribs(visualAttributes);gl.uniform1f(vu.time,time);gl.uniform1f(vu.stage,displayStage);gl.uniform1f(vu.aspect,aspect);gl.uniform1f(vu.reduced,reduced?1:0);gl.uniform1f(vu.offset,embedOffset);gl.drawArrays(gl.POINTS,0,particleCount);
  gl.blendFunc(gl.SRC_ALPHA,gl.ONE);gl.useProgram(dataProgram);bindAttribs(dataAttributes);gl.uniform1f(du.time,time);gl.uniform1f(du.stage,displayStage);gl.uniform1f(du.aspect,aspect);gl.uniform1f(du.reduced,reduced?1:0);gl.uniform1f(du.offset,embedOffset);gl.uniform1f(du.hover,hovered>=0?dataSeeds[hovered]:-1);gl.drawArrays(gl.POINTS,0,creators.length);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);
  const points=dataScreenPositions(time);let nearest=-1,bestScore=Infinity;
  points.forEach((p,i)=>{const state=creatorState(creators[i],stage);if(!p.visible||state==='hidden')return;const pending=state==='unknown'||state==='unassessed',radius=48,d=Math.hypot(pointer.x-p.x,pointer.y-p.y);if(d<=radius){const priority=0.0,score=d/radius+priority;if(score<bestScore){bestScore=score;nearest=i}}});
  if(hovered>=0&&nearest<0){const p=points[hovered],state=creatorState(creators[hovered],stage),hold=64;if(Math.hypot(pointer.x-p.x,pointer.y-p.y)<=hold)nearest=hovered}
  if(nearest!==hovered){hovered=nearest;if(nearest<0){tooltip.className='tooltip';selectionTarget.className='selection-target';selectionLine.className='selection-line'}else{selectedCreator=nearest;renderProfile();const c=creators[nearest],s=creatorState(c,stage),visualState=stage===0?'unassessed':s;tooltip.innerHTML=`<b>CREATOR ${c.id}</b>FOLLOWERS&nbsp;&nbsp;${format(c.followers)}<br>AVG. VIEWS&nbsp;&nbsp;${format(c.avgViews)}<br><span>STATUS&nbsp;&nbsp;${s==='passed'?'CONFIRMED':s==='failed'?'FILTERED':stage===0?'IN SAMPLE':'PENDING REVIEW'}</span>`;tooltip.className=`tooltip visible ${visualState}`;selectionTarget.className=`selection-target visible ${visualState}`;selectionLine.className=`selection-line visible ${visualState}`}}
  if(nearest>=0){const p=points[nearest],cardW=154,cardH=76,gap=58;let left=p.x<rect.width/2?Math.min(rect.width-cardW-12,p.x+gap):Math.max(12,p.x-gap-cardW);let top=Math.max(12,Math.min(rect.height-cardH-12,p.y-cardH/2));tooltip.style.left=`${left}px`;tooltip.style.top=`${top}px`;selectionTarget.style.left=`${p.x}px`;selectionTarget.style.top=`${p.y}px`;const endX=left>p.x?left:left+cardW,endY=top+cardH/2,dx=endX-p.x,dy=endY-p.y;selectionLine.style.left=`${p.x}px`;selectionLine.style.top=`${p.y}px`;selectionLine.style.width=`${Math.max(0,Math.hypot(dx,dy)-23)}px`;selectionLine.style.transform=`rotate(${Math.atan2(dy,dx)}rad)`}
  fpsFrames++;if(now-fpsStart>1000){const fps=Math.round(fpsFrames*1000/(now-fpsStart));window.prototypeFPS=fps;viewport.dataset.fps=String(fps);fpsFrames=0;fpsStart=now}
  window.prototypeReady=true;viewport.dataset.ready='true';requestAnimationFrame(render);
}
function format(v){if(v===null||v===undefined)return '—';return v>=1000000?`${(v/1000000).toFixed(2)}M`:v>=1000?`${(v/1000).toFixed(v<10000?1:0)}K`:String(v)}
requestAnimationFrame(render);
